"""Subarrays with K Different Integers — exactly(k) = atMost(k) - atMost(k-1).

"At most k distinct" is a plain sliding window; the difference of two of them
counts the windows with exactly k.

Time: O(n)   Space: O(k)
"""
from collections import defaultdict
from typing import List


class Solution:
    def subarraysWithKDistinct(self, nums: List[int], k: int) -> int:
        return self._at_most(nums, k) - self._at_most(nums, k - 1)

    def _at_most(self, nums: List[int], k: int) -> int:
        count = defaultdict(int)
        left = total = 0
        for right, value in enumerate(nums):
            count[value] += 1
            while len(count) > k:
                count[nums[left]] -= 1
                if count[nums[left]] == 0:
                    del count[nums[left]]
                left += 1
            total += right - left + 1
        return total
